-- Swara Ranjana — Phase 7A\n-- Customer account linking for passwordless email OTP login.\n\nalter table public.customers\n  add column if not exists auth_user_id uuid references auth.users(id) on delete set null,\n  add column if not exists account_created_at timestamptz not null default now(),\n  add column if not exists account_activated_at timestamptz,\n  add column if not exists last_login_at timestamptz;\n\ncreate unique index if not exists customers_auth_user_id_unique_idx\n  on public.customers(auth_user_id)\n  where auth_user_id is not null;\n\ncreate or replace function public.claim_customer_account()\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, auth\nas $$\ndeclare\n  v_uid uuid := auth.uid();\n  v_email text := lower(btrim(coalesce(auth.jwt() ->> 'email', '')));\n  v_customer_id uuid;\n  v_existing_uid uuid;\nbegin\n  if v_uid is null or v_email = '' then\n    raise exception 'Authenticated email is required' using errcode = '42501';\n  end if;\n\n  select id, auth_user_id\n    into v_customer_id, v_existing_uid\n    from public.customers\n   where lower(email) = v_email\n   for update;\n\n  if not found then\n    raise exception 'No customer account exists for this email' using errcode = 'P0002';\n  end if;\n\n  if v_existing_uid is not null and v_existing_uid <> v_uid then\n    raise exception 'Customer account is already linked' using errcode = '42501';\n  end if;\n\n  update public.customers\n     set auth_user_id = v_uid,\n         account_activated_at = coalesce(account_activated_at, now()),\n         last_login_at = now(),\n         updated_at = now()\n   where id = v_customer_id;\n\n  return v_customer_id;\nend;\n$$;\n\nrevoke all on function public.claim_customer_account() from public;\ngrant execute on function public.claim_customer_account() to authenticated;\n\ndrop policy if exists customers_self_read on public.customers;\ncreate policy customers_self_read on public.customers for select to authenticated\nusing (auth_user_id = auth.uid());\n\ndrop policy if exists orders_customer_read on public.orders;\ncreate policy orders_customer_read on public.orders for select to authenticated\nusing (exists (select 1 from public.customers c where c.id = orders.customer_id and c.auth_user_id = auth.uid()));\n\ndrop policy if exists order_items_customer_read on public.order_items;\ncreate policy order_items_customer_read on public.order_items for select to authenticated\nusing (exists (select 1 from public.orders o join public.customers c on c.id=o.customer_id where o.id=order_items.order_id and c.auth_user_id=auth.uid()));\n\ndrop policy if exists tickets_customer_read on public.tickets;\ncreate policy tickets_customer_read on public.tickets for select to authenticated\nusing (exists (select 1 from public.customers c where c.id=tickets.customer_id and c.auth_user_id=auth.uid()));\n\ndrop policy if exists payment_submissions_customer_read on public.payment_submissions;\ncreate policy payment_submissions_customer_read on public.payment_submissions for select to authenticated\nusing (exists (select 1 from public.orders o join public.customers c on c.id=o.customer_id where o.id=payment_submissions.order_id and c.auth_user_id=auth.uid()));\n\ndrop policy if exists events_customer_order_read on public.events;\ncreate policy events_customer_order_read on public.events for select to authenticated\nusing (exists (select 1 from public.orders o join public.customers c on c.id=o.customer_id where o.event_id=events.id and c.auth_user_id=auth.uid()));\n\ndrop policy if exists ticket_types_customer_order_read on public.ticket_types;\ncreate policy ticket_types_customer_order_read on public.ticket_types for select to authenticated\nusing (exists (select 1 from public.order_items oi join public.orders o on o.id=oi.order_id join public.customers c on c.id=o.customer_id where oi.ticket_type_id=ticket_types.id and c.auth_user_id=auth.uid()));\n